mapper.insert:
INSERT INTO app.app_user (
    id, username, nickname, password_hash, role, status, current_zone_period_id, password_changed_at
) VALUES (
    #{id}, #{username}, #{nickname}, #{passwordHash}, 'USER', 'ENABLED',
    #{currentZonePeriodId}, clock_timestamp()
)

INSERT INTO app.captcha_challenge (
    id, purpose, binding_digest, verification_data, created_at, expires_at, create_key, state
) VALUES (
    #{id}, #{purpose}, #{bindingDigest}, #{verificationData}, #{createdAt}, #{expiresAt}, #{createKey}, 'ISSUED'
)

mapper.delete:
WITH expired_captcha AS (
    DELETE FROM app.captcha_challenge
    WHERE id IN (SELECT id FROM app.captcha_challenge
        WHERE expires_at < clock_timestamp() - INTERVAL '10 minutes' LIMIT 100)
), expired_attempt AS (
    DELETE FROM app.login_attempt WHERE username_key IN (
        SELECT username_key FROM app.login_attempt WHERE retain_until < clock_timestamp() LIMIT 100
    )
)
DELETE FROM app.request_dedup WHERE id IN (
    SELECT id FROM app.request_dedup
    WHERE expires_at < clock_timestamp() AND state != 'PROCESSING' LIMIT 100
)

DELETE FROM session_store.spring_session_attributes WHERE session_primary_id IN (
    SELECT primary_id FROM session_store.spring_session WHERE session_id = #{sessionId} FOR UPDATE
)

DELETE FROM session_store.spring_session_attributes WHERE session_primary_id IN (
    SELECT primary_id FROM session_store.spring_session WHERE principal_name = CAST(#{userId} AS TEXT) FOR UPDATE
)

mapper.select:
SELECT EXISTS (SELECT 1 FROM app.request_dedup
    WHERE operation = 'API-AUTH-009' AND idempotency_key = #{context.key}
        AND scope_key != #{context.scope} AND expires_at > clock_timestamp())
